'use strict';
const ioAPI=globalThis.RasnikiIO,node=id=>document.getElementById(id);let botResult='',importRevision=0;
function invalidate(){importRevision++;}
for(const id of ['text','edition'])node(id).addEventListener(id==='text'?'input':'change',invalidate);
function download(content,name,type){const url=URL.createObjectURL(new Blob([content],{type})),link=document.createElement('a');link.href=url;link.download=name;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
node('text-export').addEventListener('click',()=>download(node('text').value,'rasniki-'+node('edition').value+'.txt','text/plain;charset=utf-8'));
node('json-export').addEventListener('click',()=>{try{download(ioAPI.pack(node('text').value,node('edition').value),'rasniki-io.json','application/json');node('io-status').textContent='JSON record exported.';}catch(e){node('io-status').textContent=e.message;}});
node('clear').addEventListener('click',()=>{invalidate();node('text').value='';node('edition').value='english';node('file').value='';node('io-status').textContent='Working text cleared.';});
node('file').addEventListener('change',async()=>{const file=node('file').files[0];if(!file)return;const revision=++importRevision;if(file.size>1000000){node('io-status').textContent='Import limit is 1,000,000 bytes.';return;}try{const bytes=await file.arrayBuffer();const text=new TextDecoder('utf-8',{fatal:true}).decode(bytes);const record=file.name.toLowerCase().endsWith('.json')?ioAPI.unpack(text):{text,edition:'english'};if(record.text.length>100000)throw Error('Working text limit is 100,000 UTF-16 units');if(revision!==importRevision)return;node('text').value=record.text;node('edition').value=record.edition;node('io-status').textContent='Imported locally: '+file.name;}catch(e){if(revision===importRevision)node('io-status').textContent='Import failed: '+e.message;}});
function convert(direction){try{invalidate();node('text').value=ioAPI[direction](node('text').value);node('edition').value=direction==='encode'?'iau':'english';node('io-status').textContent='Converted. English letter case is folded.';}catch(e){node('io-status').textContent=e.message;}}
node('encode').addEventListener('click',()=>convert('encode'));node('decode').addEventListener('click',()=>convert('decode'));
for(let i=0;i<ioAPI.letters.length;i++){const span=document.createElement('span');span.className='rune';span.textContent=ioAPI.letters[i]+' → '+ioAPI.runes[i];node('alphabet').append(span);}
function runCommand(){try{botResult=ioAPI.command(node('command').value);node('bot-output').textContent=botResult;}catch(e){botResult='';node('bot-output').textContent='Command error: '+e.message;}}
node('run').addEventListener('click',runCommand);node('command').addEventListener('keydown',e=>{if(e.key==='Enter')runCommand();});node('command').addEventListener('input',()=>{botResult='';node('bot-output').textContent='Command changed. Run it to obtain a new result.';});
node('copy-output').addEventListener('click',()=>{if(!botResult){node('io-status').textContent='Run a successful command first.';return;}invalidate();node('text').value=botResult;node('edition').value=node('command').value.trim().toLowerCase().startsWith('runes ')?'iau':'english';node('io-status').textContent='Command result copied to working text.';});runCommand();
